		return b, mapErr(err)
	}
	b.Principal.Type = rbac.PrincipalType(ptype)
	b.ResourceType = rbac.ResourceType(rtype)
	r, ok := rbac.ParseRole(role)
	if !ok {
		return b, fmt.Errorf("pgstore: unknown role %q", role)
	}
	b.Role = r
	return b, nil
}

