	for s := cur - Skew; s <= cur+Skew; s++ {
		if s < 0 {
			continue
		}
		if subtle.ConstantTimeCompare([]byte(Code(secret, s)), []byte(code)) == 1 && matched < 0 {
			matched = s
		}
	}
